def tick(self,launch_queued=True):
        with self.lock:
            if self.lifecycle not in {"running","draining"}:return
            # Explicit cancel/shutdown TERM is attempted before slow/failing
            # scans. Repeated ticks provide bounded owned SIGKILL escalation.
            self._service_termination()
            try:
                if time.time()>=self.cap["expires_unix"] and self.lifecycle=="running":
                    self.lifecycle="draining"
                    for job in self.jobs.values():
                        if job["state"]=="queued":job.update(state="cancelled",finished_unix=time.time(),error="Pool submission authority expired; owned drain continues")
                self._lease_check();self._drain_logs();self._process_scan();self._reap_owned_adopted();memory=self._memory()
                self.safety_error=None
                if memory["overrun_jobs"]:
                    self._fail_owned_supervision("Owned GPU reservation overrun; drain required")
                for name,child in list(self.children.items()):
                    job=self.jobs[name];exit_code=child.poll()
                    if exit_code is not None:
                        job.update(exit_code=exit_code,state="draining",leader_wait_status_known=True)
                        self._process_scan();self._reap_owned_adopted();memory=self._memory()
                        live=name in self.pid_jobs.values()
                        own_compute=name in memory["owned_compute_jobs"]
                        if not live and not own_compute and not self.ambiguous:
                            descendant_ok=all(r["returncode"]==0 for r in job["descendant_waits"])
                            self._drain_logs();job.update(state="succeeded" if exit_code==0 and descendant_ok and not job.get("resource_abort") and not job.get("cancel_requested") else "failed",finished_unix=time.time(),owned_drain_observed=True)
                            if child.stdout is not None:child.stdout.close()
                            self.logs.pop(name).close();del self.children[name]
                if launch_queued:self._launch_queue()
                if self.lifecycle=="draining" and not self.children and not self.ambiguous:self.lifecycle="closed"
            except Exception as error:
                self._fail_owned_supervision(f"{type(error).__name__}: {error}")
            finally:
                # Includes scan/guard errors. Do not depend on persistence to
                # send a previously authorised, exact owned PIDFD signal.
                self._service_termination()
            try:self._persist()
            except Exception as error:
                self._fail_owned_supervision("Controller persistence failed: "+f"{type(error).__name__}: {error}")
                self._service_termination()

def run(self, poll_seconds=1.0):
        """Bounded one-request connections; waiting clients never stop supervision."""
        selector = selectors.DefaultSelector()
        selector.register(self.listener, selectors.EVENT_READ, None)
        clients = {}
        normal = False
        def drop(conn):
            clients.pop(conn, None)
            try:
                selector.unregister(conn)
            except KeyError:
                pass
            conn.close()
        try:
            while self.lifecycle != "closed" or clients:
                now = time.monotonic()
                if self.shutdown_requested:
                    self.shutdown_requested = False
                    self.shutdown(terminate=False)
                if now >= self.next_poll:
                    self.tick()
                    self.next_poll = time.monotonic() + poll_seconds
                for conn, state in list(clients.items()):
                    if now > state["deadline"]:
                        drop(conn)
                for key, events in selector.select(timeout=min(poll_seconds, .25)):
                    if key.fileobj is self.listener:
                        conn, _ = self.listener.accept()
                        try:
                            peer = struct.unpack("3i", conn.getsockopt(socket.SOL_SOCKET, socket.SO_PEERCRED, 12))
                            if peer[1] != os.getuid() or len(clients) >= 32:
                                conn.close()
                                continue
                        except Exception:
                            conn.close()
                            continue
                        conn.setblocking(False)
                        clients[conn] = dict(input=bytearray(), output=b"", deadline=time.monotonic() + 30)
                        selector.register(conn, selectors.EVENT_READ, clients[conn])
                        continue
                    conn, state = key.fileobj, key.data
                    try:
                        if events & selectors.EVENT_READ:
                            chunk = conn.recv(8192)
                            if not chunk:
                                drop(conn)
                                continue
                            state["input"].extend(chunk)
                            if len(state["input"]) > MAX_REQUEST:
                                raise ValueError("Request exceeds size limit")
                            if b"\n" in state["input"]:
                                line, remainder = bytes(state["input"]).split(b"\n", 1)
                                if remainder:
                                    raise ValueError("One request per connection required")
                                try:
                                    answer = dict(ok=True, result=self.dispatch(json.loads(line)))
                                except Exception as error:
                                    answer = dict(ok=False, error=f"{type(error).__name__}: {error}")
                                state["output"] = encoded(answer) + b"\n"
                                if len(state["output"]) > MAX_REPLY:
                                    raise ValueError("Response exceeds size limit")
                                selector.modify(conn, selectors.EVENT_WRITE, state)
                        if events & selectors.EVENT_WRITE:
                            sent = conn.send(state["output"])
                            state["output"] = state["output"][sent:]
                            if not state["output"]:
                                drop(conn)
                    except (OSError, ValueError):
                        drop(conn)
            normal = True
        finally:
            for conn in list(clients):
                drop(conn)
            selector.close()
            if normal:
                self.close()
            else:
                self.lifecycle = "controller_error"
                self._persist()
                # Crash/error handling does not unlock inherited leases or kill users.
                self._release_handles()

def close(self):
        with self.lock:
            if self.children or self.ambiguous or self.lifecycle != "closed":
                raise RuntimeError("Graceful close requires fully drained shutdown")
            self._release_handles()

def _release_handles(self):
        if self.listener is not None:
            # Only unlink the socket this controller actually bound.
            try:
                bound = self.listener.getsockname()
            except OSError:
                bound = ""
            self.listener.close()
            self.listener = None
            if bound == str(self.socket_path):
                try:
                    current = self.socket_path.lstat()
                    if (current.st_dev, current.st_ino) == self.socket_inode:
                        self.socket_path.unlink()
                except FileNotFoundError:
                    pass
        if self.lease is not None:
            self.lease.close()  # Never LOCK_UN: inherited workers can still hold the OFD.
            self.lease = None
